% Define the ultrasound signal (voltage vs time)
fs = 4000; % Sampling frequency (Hz)
t = 0:1/fs:1; % Time vector (1 second)
f0 = 1e6; % Frequency of the ultrasound signal (1 MHz)
signal = sin(2*pi*f0*t); % Ultrasound signal

% Perform FFT on the signal to get the magnitude vs frequency
nfft = length(signal); % Number of FFT points
Y = fft(signal, nfft); % Compute the FFT
f = fs*(0:(nfft/2))/nfft; % Frequency vector
magnitude = 20*log10(abs(Y(1:nfft/2+1))); % Magnitude in dB

% Plot the magnitude vs frequency
figure;
plot(f/1e6, magnitude);
xlabel('Frequency (MHz)');
ylabel('Magnitude (dB)');
title('Ultrasound Signal Spectrum');

